import { Bar, BarChart, Rectangle, ResponsiveContainer, Tooltip, XAxis } from 'recharts'
import CustomizedAxisTick from './CustomizedAxisTick'
import EmptyTooltip from './EmptyTooltip'

const VolumeChart = ({ data, onChangeValue }: { data: any; onChangeValue: (data: any) => void }) => {
  const handleMouseMove = (e: any) => {
    if (e && e.activePayload && e.activePayload.length) {
      onChangeValue(e.activePayload[0].payload)
    }
  }

  const handleMouseLeave = () => {
    onChangeValue(null)
  }

  return (
    <ResponsiveContainer width="100%" height="100%">
      <BarChart data={data} onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
        <XAxis type="category" dataKey="month" minTickGap={18} tickLine={false} axisLine={false} tick={<CustomizedAxisTick />} />
        <Tooltip content={<EmptyTooltip />} cursor={{ fill: 'rgba(118,200,255,0.5)' }} />
        <Bar dataKey="num" fill="#6FBCF0" activeBar={<Rectangle fill="#fff" stroke="rgba(0,0,0,0)" />} isAnimationActive={false} />
      </BarChart>
    </ResponsiveContainer>
  )
}

export default VolumeChart
