import { TooltipIcon } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { HStack, HTMLChakraProps, PlacementWithLogical, Text, VStack } from '@chakra-ui/react'

interface TableSortThProps extends HTMLChakraProps<'div'> {
  labelInfo: { label: string; value: string }
  tooltip?: { type: string; placement?: PlacementWithLogical; xlinkHref?: string }
  sortRule: string
  sortBy: { label: string; value: string }
  clickSort: (value: any) => void
}
export default function TableSortTh({
  labelInfo,
  tooltip = { type: '', placement: 'top', xlinkHref: '#icon-icon_tips' },
  sortRule = 'desc',
  sortBy,
  clickSort,
  ...rest
}: TableSortThProps) {
  const { isApp } = useWindowWidth()
  const { type, placement, xlinkHref } = tooltip
  return (
    <HStack cursor="pointer" gap="0px" {...rest} onClick={() => clickSort(labelInfo)}>
      <Text fontSize="14px">{labelInfo.label}</Text>
      {tooltip?.type && <TooltipIcon type={type} placement={placement} xlinkHref={xlinkHref} />}
      {!isApp && (
        <VStack h="20px" gap="0">
          <Icon
            xlinkHref="#icon-icon_ascending_nor"
            svgH="10px"
            svgHover="primary"
            svgFill={labelInfo.value == sortBy?.value && sortRule == 'asc' ? 'primary' : ''}
          />
          <Icon
            xlinkHref="#icon-icon_descending_nor"
            svgH="10px"
            svgHover="primary"
            svgFill={labelInfo.value == sortBy?.value && sortRule == 'desc' ? 'primary' : ''}
          />
        </VStack>
      )}
    </HStack>
  )
}
