import { bnAmountNumericAbbreviation } from '@/utils/api-data-utils'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { Icon, SingleCoinImage } from '@cetus/ui-kit'
import { HStack, Skeleton, Text } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

export default function TransTypeValue({ transInfo, tdType }: { transInfo: any; tdType: 'type' | 'tokenAmountA' | 'tokenAmountB' }) {
  const { getExplorerUrl } = useExplorer()
  const { getTokenInfo } = useGetToken()
  const [tokenA, setTokenA] = useState<any>(null)
  const [tokenB, setTokenB] = useState<any>(null)

  useEffect(() => {
    const fetchTokenA = async () => {
      if (!transInfo?.coinTypeA) return
      try {
        const coinInfo = await getTokenInfo(transInfo?.coinTypeA)
        if (transInfo?.coinTypeA == '0x81592dd2a469c442b7edf88eb353b2bdf37404aa4f1bac312b70d348540dac79::wc::WC') {
          console.log('🚀 ~ fetchTokenA ~ coinInfo:', coinInfo)
        }
        setTokenA(coinInfo)
      } catch (error) {
        console.error('Error fetching token info:', error)
      }
    }
    const fetchTokenB = async () => {
      if (!transInfo?.coinTypeB) return
      try {
        const coinInfo = await getTokenInfo(transInfo?.coinTypeB)
        setTokenB(coinInfo)
      } catch (error) {
        console.error('Error fetching token info:', error)
      }
    }
    fetchTokenA()
    fetchTokenB()
  }, [transInfo?.coinTypeA, transInfo?.coinTypeB])

  const getLabel = (type: string) => {
    switch (type) {
      case 'swap':
        return 'Swap'
      case 'remove':
        return 'Remove'
      case 'add':
        return 'Add'
    }
  }

  return (
    <Skeleton isLoaded={!!tokenA || !!tokenB}>
      {tdType == 'type' ? (
        <HStack gap="4px">
          {transInfo?.coinTypeA && <Text color="text_caption">{getLabel(transInfo?.txType)}</Text>}
          {transInfo?.coinTypeA && (
            <SingleCoinImage imageUrl={tokenA?.logo_url} w="16px" h="16px" showTag={!tokenA?.is_trusted} showTagWidth="8px" showTagHeight="8px" />
          )}
          {transInfo?.coinTypeA && <Text color="text_caption">{tokenA?.symbol || '--'}</Text>}
          {transInfo?.coinTypeA && transInfo?.coinTypeB && <Text color="text_caption">{transInfo?.txType == 'swap' ? 'for' : 'and'}</Text>}
          {transInfo?.coinTypeB && (
            <SingleCoinImage imageUrl={tokenB?.logo_url} w="16px" h="16px" showTag={!tokenB?.is_trusted} showTagWidth="8px" showTagHeight="8px" />
          )}
          {transInfo?.coinTypeB && <Text color="text_caption">{tokenB?.symbol || '--'}</Text>}
          <Icon
            xlinkHref="#icon-icon_link"
            onClick={() => {
              window.open(getExplorerUrl(transInfo?.tx, 'tx'), '_blank')
            }}
          />
        </HStack>
      ) : tdType == 'tokenAmountA' ? (
        <HStack gap="4px">
          <Text color="text_caption">{bnAmountNumericAbbreviation(transInfo?.tokenAmountA, 2)}</Text>
          <Text color="text_caption">{tokenA?.symbol}</Text>
        </HStack>
      ) : (
        <HStack gap="4px">
          <Text color="text_caption">{bnAmountNumericAbbreviation(transInfo?.tokenAmountB, 2)}</Text>
          <Text color="text_caption">{tokenB?.symbol}</Text>
        </HStack>
      )}
    </Skeleton>
  )
}
