import icon_fee from '@/assets/images/icon_fee@2x.png'
import icon_mining from '@/assets/images/icon_rewards@2x.png'
import { cancelBubble } from '@cetus/utils'
import { Box, Center, HStack, Image, Popover, PopoverBody, PopoverContent, PopoverTrigger, Portal, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'
const AprTooltip = ({ poolInfo }: { poolInfo: any }) => {
  const [isShowInfo, setIsShowInfo] = useState(false)

  return (
    <HStack
      justify="flex-end"
      w="100%"
      onClick={e => cancelBubble(e)}
      onMouseEnter={() => setIsShowInfo(true)}
      onMouseLeave={() => setIsShowInfo(false)}
    >
      <Popover isOpen={isShowInfo} placement="top">
        <PopoverTrigger>
          <Center>
            <AprInfo poolInfo={poolInfo} />
          </Center>
        </PopoverTrigger>
        {isShowInfo && (
          <Portal>
            <PopoverContent zIndex="2" minW="unset" w="unset" border="1px solid" borderColor="border" p="4px ">
              <PopoverBody borderRadius="12px">
                <TooltipInfo poolInfo={poolInfo} />
              </PopoverBody>
            </PopoverContent>
          </Portal>
        )}
      </Popover>
    </HStack>
  )
}

const AprInfo = ({ poolInfo }: { poolInfo: any }) => {
  return (
    <VStack align="flex-end">
      <Text color="primary">{poolInfo?.feeAndMiningAprDisplay}</Text>
      {poolInfo?.haveFarming && (
        <Text p="2px 4px" fontSize="12px" color="primary_yellow" bg="primary_yellow_opacity.10" borderRadius="8px">
          +{poolInfo?.farmingAprDisplay}
        </Text>
      )}
    </VStack>
  )
}

const TooltipInfo = ({ poolInfo }: { poolInfo: any }) => {
  return (
    <VStack gap="16px" w="280px" align="flex-start">
      <Text textAlign="left" w="100%" whiteSpace="wrap" fontSize="12px">
        {poolInfo?.haveMining && poolInfo?.haveFarming
          ? 'Estimated according to trading activity in the past 24 hours plus mining and farming rewards'
          : poolInfo?.haveMining
            ? 'Estimated according to trading activity in the past 24 hours plus mining rewards'
            : poolInfo?.haveFarming
              ? 'Estimated according to trading activity in the past 24 hours plus farming rewards'
              : ' Estimated according to trading activity in the past 24 hours'}
      </Text>
      <Box h="1px" w="100%" bg="border" />
      <HStack w="100%" justify="space-between">
        <HStack>
          <Image w="20px" h="20px" src={icon_fee} />
          <Text fontSize="12px">Fees</Text>
        </HStack>
        <Text color="text_caption" fontSize="12px">
          {poolInfo?.feeAprDisplay}
        </Text>
      </HStack>
      {poolInfo?.haveMining && (
        <VStack position="relative" w="100%" align="flex-start" justify="space-between">
          <HStack
            sx={{
              _after: {
                content: '""',
                display: 'inline-block',
                width: '1px',
                height: ' calc(100% - 38px)',
                background: 'text_paragraph',
                position: 'absolute',
                left: '10px',
                top: '30px'
              }
            }}
          >
            <Image w="20px" h="20px" src={icon_mining} />
            <Text fontSize="12px">Mining</Text>
          </HStack>
          <VStack w="100%" pl="28px" mt="8px">
            {poolInfo?.miningAprList?.map((item: any) => {
              return (
                <HStack position="relative" key={item?.symbol} w="100%" justify="space-between">
                  <Text
                    fontSize="12px"
                    sx={{
                      _after: {
                        content: '""',
                        display: 'inline-block',
                        width: '13px',
                        height: '1px',
                        background: 'text_paragraph',
                        position: 'absolute',
                        left: '-18px',
                        top: '50%',
                        transform: 'translateY(-50%)'
                      }
                    }}
                  >
                    {item?.symbol} Rewards
                  </Text>
                  <Text fontSize="12px" color="text_caption">
                    {item?.aprDisplay}
                  </Text>
                </HStack>
              )
            })}
          </VStack>
        </VStack>
      )}
      {poolInfo?.haveFarming && (
        <HStack w="100%" justify="space-between" borderRadius="12px" p="8px 12px" bg="primary_yellow_opacity.10">
          <VStack align="flex-start" gap="4px">
            <Text color="primary_yellow" fontSize="12px">
              Farming
            </Text>
            <Text color="white_color_opacity.80" fontSize="12px">
              Stake Position to Earn
            </Text>
          </VStack>
          <Text color="text_caption">{poolInfo?.farmingAprDisplay}</Text>
        </HStack>
      )}
      <HStack w="100%" justify="space-between">
        <Text color="text_caption">Total APR</Text>
        <Text color="text_caption" fontSize="16px">
          {poolInfo?.totalAprDisplay}
        </Text>
      </HStack>
    </VStack>
  )
}
export default AprTooltip
