import vaults_gif from '@/assets/images/icon_autopools@2x.gif'
import vaults_png from '@/assets/images/icon_autopools@2x.png'
import { cancelBubble } from '@cetus/utils'
import { HStack, Image, Text, Tooltip } from '@chakra-ui/react'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

const MiningIcon = () => {
  const navigate = useNavigate()
  const [isShowGif, setIsShowGif] = useState(false)
  return (
    <HStack
      w="20px"
      h="20px"
      onClick={e => {
        cancelBubble(e)
        navigate('/vaults')
      }}
      onMouseEnter={() => setIsShowGif(true)}
      onMouseLeave={() => {
        setIsShowGif(false)
      }}
    >
      <Tooltip label={<Text fontSize="12px">Vault available</Text>} aria-label="Yield" placement="top">
        {isShowGif ? (
          <Image
            w="100%"
            h="100%"
            src={vaults_gif}
            onMouseLeave={() => {
              setIsShowGif(false)
            }}
          />
        ) : (
          <Image w="100%" h="100%" src={vaults_png} onMouseEnter={() => setIsShowGif(true)} />
        )}
      </Tooltip>
    </HStack>
  )
}

export default MiningIcon
