import { useGetToken } from '@cetus/hooks/src/useToken'
import { SingleCoinImage } from '@cetus/ui-kit'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

// 没有token信息时可以只传coin_type
const SingleTokenInfo = ({ token, coinType }: { token?: any; coinType?: string }) => {
  const { getTokenInfo } = useGetToken()
  const [tokenInfo, setTokenInfo] = useState<any>(token)

  useEffect(() => {
    const fetchToken = async () => {
      if (!coinType) return
      try {
        const coinInfo = await getTokenInfo(coinType)
        setTokenInfo(coinInfo)
      } catch (error) {
        console.error('Error fetching token info:', error)
      }
    }
    fetchToken()
  }, [coinType])

  return (
    <HStack>
      <SingleCoinImage imageUrl={tokenInfo?.logo_url} />
      <VStack align="flex-start" gap="0">
        <Text color="text_caption">{tokenInfo?.symbol}</Text>
        <Text fontSize="12px">{tokenInfo?.name}</Text>
      </VStack>
    </HStack>
  )
}

export default SingleTokenInfo
