import icon_accounts from '@/assets/images/icon_accounts@2x.png'
import icon_cumulativetransactions from '@/assets/images/icon_cumulativetransactions@2x.png'
import icon_cumulativevolume from '@/assets/images/icon_cumulativevolume@2x.png'
import icon_totalvaluelocked from '@/assets/images/icon_totalvaluelocked@2x.png'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { HStack, Image, Skeleton, Text, VStack } from '@chakra-ui/react'

export default function Statistics({ statisticsData }: { statisticsData: any }) {
  const { isApp } = useWindowWidth()
  return (
    <HStack
      w="100%"
      justifyContent="space-between"
      flexWrap={{
        base: 'wrap',
        lg: 'nowrap'
      }}
      sx={{
        '>div': {
          w: isApp ? 'calc(50% - 16px)' : '25%'
        }
      }}
    >
      <InfoData label="Cumulative Volume" value={statisticsData?.cumulativeVolume} imgSrc={icon_accounts} />
      <InfoData label="Total Value Locked" value={statisticsData?.totalValueLocked} imgSrc={icon_cumulativetransactions} />
      <InfoData label="Cumulative Transactions" value={statisticsData?.cumulativeTransactions} imgSrc={icon_cumulativevolume} />
      <InfoData label="Total Accounts" value={statisticsData?.totalAccounts} imgSrc={icon_totalvaluelocked} />
    </HStack>
  )
}

const InfoData = ({ label, value, imgSrc }: { label: string; value: string; imgSrc: string }) => {
  return (
    <VStack
      mt="40px"
      align={{
        base: 'flex-start',
        lg: 'center'
      }}
    >
      <VStack
        flexDirection={{
          base: 'row',
          lg: 'column'
        }}
      >
        <Image src={imgSrc} w="34px" h="34px" />
        <Text
          whiteSpace="nowrap"
          fontSize={{
            base: '12px',
            lg: '14px'
          }}
        >
          {label}
        </Text>
      </VStack>
      <Skeleton isLoaded={!!value}>
        <Text
          fontSize={{
            base: '16px',
            lg: '18px'
          }}
          color="text_caption"
        >
          {value}
        </Text>
      </Skeleton>
    </VStack>
  )
}
