import mining_png from '@/assets/images/icon_rewards@2x.png'
import mining_gif from '@/assets/images/rewards.gif'
import { HStack, Image, Text, Tooltip } from '@chakra-ui/react'
import { useState } from 'react'

const MiningIcon = () => {
  const [isShowGif, setIsShowGif] = useState(false)
  return (
    <HStack
      w="20px"
      h="20px"
      onMouseEnter={() => setIsShowGif(true)}
      onMouseLeave={() => {
        setIsShowGif(false)
      }}
    >
      <Tooltip label={<Text fontSize="12px">Mining rewards available</Text>} aria-label="Yield" placement="top">
        {isShowGif ? (
          <Image
            w="100%"
            h="100%"
            src={mining_gif}
            onMouseLeave={() => {
              setIsShowGif(false)
            }}
          />
        ) : (
          <Image w="100%" h="100%" src={mining_png} onMouseEnter={() => setIsShowGif(true)} />
        )}
      </Tooltip>
    </HStack>
  )
}

export default MiningIcon
