import { Icon } from '@cetus/ui-kit'
import { Box, Button, HStack, Menu, MenuButton, MenuList, Text } from '@chakra-ui/react'
import { useState } from 'react'

const SortDropBlock = ({
  sortText,
  minW,
  currentSort,
  onSortByChange,
  sortByList
}: {
  sortText: string
  minW: string
  currentSort: any
  onSortByChange: (type: any) => void
  sortByList: any
}) => {
  const [isOpen, setIsOpen] = useState(false)
  return (
    <Menu
      isOpen={isOpen}
      onClose={() => {
        setIsOpen(false)
      }}
    >
      <MenuButton
        w={minW || 'unset'}
        isActive={isOpen}
        as={Button}
        bg="bg_secondary"
        borderRadius="12px"
        border="1px solid"
        borderColor="border"
        h="40px"
        p="0px 10px"
        sx={{
          _hover: {
            bg: 'bg_secondary',
            '.drop-icon': {
              svg: {
                fill: 'text_caption'
              }
            }
          },
          _active: {
            bg: 'bg_secondary'
          }
        }}
        onClick={() => {
          setIsOpen(true)
        }}
      >
        <HStack align="center" justifyContent="space-between">
          <HStack gap="8px">
            <Icon xlinkHref="#icon-icon_type" variant="gray" />
            <Text color="text_paragraph">{sortText}</Text>
          </HStack>
          <HStack gap="8px">
            <Text color="text_caption">{currentSort?.label}</Text>
            <Box className="drop-icon">
              <Icon
                svgW="16px"
                xlinkHref="#icon-icon_arrow"
                variant="gray"
                transition="transform 0.5s"
                transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
              />
            </Box>
          </HStack>
        </HStack>
      </MenuButton>
      <MenuList p="0" opacity="1" overflow="hidden" minW={minW || 'unset'}>
        {sortByList.map((item: any) => {
          return (
            <Text
              sx={{
                _hover: {
                  bg: 'card_bg'
                }
              }}
              h="45px"
              lineHeight="45px"
              textAlign="center"
              color="text_caption"
              key={item.value}
              cursor="pointer"
              onClick={() => {
                onSortByChange(item)
                setIsOpen(false)
              }}
            >
              {item.label}
            </Text>
          )
        })}
      </MenuList>
    </Menu>
  )
}

export default SortDropBlock
